# Now I need to find the rule. Let me look at the structure more carefully.
# The transform seems to: change some 8s to 5s based on some relationship to the existing 5s.
# 
# Let me find the connected components and see what's going on.

from collections import deque

def connected_components(grid, start_r, start_c, target_color):
    """Find connected cells of target_color connected to (start_r, start_c)"""
    h, w = len(grid), len(grid[0])
    visited = set()

    while (start_r, start_c) not in visited:
        visited.add((start_r, start_c))
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = start_r + dr, start_c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                start_r, start_c = nr, nc

    return visited

def find_color_regions(grid):
    """Find all connected regions of each non-background color"""
    h, w = len(grid), len(grid[0])
    backgr = max(set(grid[0]) if grid else [0], key=lambda c: sum(1 for r in grid for x in r if x == c))

    visited = set()
    regions = {}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != backgr and (r, c) not in visited:
                color = grid[r][c]
                region = set()

                # BFS
                q = deque([(r, c)])
                while q:
                    cr, cc = q.popleft()
                    if (cr, cc) not in visited and grid[cr][cc] == color:
                        visited.add((cr, cc))
                        region.add((cr, cc))
                        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                                q.append((nr, nc))

                regions[color] = regions.get(color, []) + [region]

    return backgr, regions

